insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('EXEC','الإدارة التنفيذية (نائب الرئيس للتشغيل)','الإدارة التنفيذية','mgmt','0D2B45','الاعتماد الاستراتيجي والمالي فوق الحدود الداخلية، وتوجيه الأولويات.','["اعتماد الخطة والميزانية السنوية للمشاريع والصيانة", "القرارات فوق حدود صلاحية مدير الإدارة", "التصعيد النهائي للتحديات"]'::jsonb,0) on conflict (code) do nothing;
insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('DIR','مدير إدارة الخدمات الفنية','مدير الإدارة','mgmt','123B5C','قيادة الإدارة بأقسامها السبعة وضبط التكامل بينها واعتماد ما يقع ضمن صلاحياته.','["اعتماد الدراسات والميزانيات التقديرية ضمن الصلاحية", "الفصل في تداخل الاختصاص بين الأقسام", "مراجعة مؤشرات الأداء الشهرية للأقسام"]'::jsonb,1) on conflict (code) do nothing;
insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('PRJ','قسم المشاريع','المشاريع','unit','27A8DF','دراسة الاحتياجات الإنشائية وتحويلها إلى مشاريع مدروسة ومطروحة ومنفَّذة ومُسلَّمة للتشغيل.','["دراسة الاحتياج والجدوى والميزانية التقديرية", "التصميم والمخططات ووثائق الطرح وجداول الكميات", "الإشراف على التنفيذ والمستخلصات وأوامر التغيير", "الاستلام الابتدائي والنهائي والتسليم للمرافق والصيانة", "متابعة الضمان مع المقاول"]'::jsonb,2) on conflict (code) do nothing;
insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('FAC','قسم المرافق','المرافق','unit','2E8B57','إدارة أصول المباني والمساحات، ونقطة الاستقبال الموحدة لاحتياجات المنشآت وتصنيفها وتوجيهها.','["سجل الأصول والمساحات والمخططات المعتمدة لكل منشأة", "استقبال احتياجات المنشآت وتصنيفها وتوجيهها للقسم المختص", "إدارة المساحات وإعادة التوزيع والانتقال", "استلام المشاريع المنجزة وتحديث سجل الأصول", "متابعة اشتراطات الدفاع المدني والسلامة الإنشائية للمباني"]'::jsonb,3) on conflict (code) do nothing;
insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('MNT','قسم الصيانة','الصيانة','unit','B8860B','إبقاء المباني وأنظمتها (كهرباء، تكييف، سباكة، إطفاء، مصاعد) عاملة بالصيانة الوقائية والتصحيحية.','["البلاغات التصحيحية وإصلاح الأعطال ضمن المهل", "خطة الصيانة الوقائية الدورية (PPM) للأنظمة", "متابعة عقود الصيانة والتشغيل ومقاوليها", "الأعمال الصغيرة التي لا ترقى إلى مشروع", "المشاركة في استلام المشاريع ومتابعة عيوب الضمان"]'::jsonb,4) on conflict (code) do nothing;
insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('BME','قسم الصيانة الطبية (الهندسة الطبية الحيوية)','الصيانة الطبية','unit','A0522D','ضمان جاهزية الأجهزة الطبية وسلامتها بالصيانة والمعايرة وعقود الخدمة.','["أعطال الأجهزة الطبية والاستجابة بحسب الخطورة", "الصيانة الوقائية والمعايرة وفق الشركة الصانعة", "استلام الأجهزة الجديدة بعد التركيب والتشغيل التجريبي", "إدارة عقود خدمة الأجهزة وقطع الغيار", "إخراج الأجهزة من الخدمة والتكهين الفني"]'::jsonb,5) on conflict (code) do nothing;
insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('MED','قسم التجهيزات الطبية','التجهيزات الطبية','unit','6B4C9A','تحديد احتياجات المنشآت من الأجهزة والتجهيزات الطبية وتوفيرها وتجهيز مواقعها.','["حصر الاحتياجات والمواصفات الفنية للأجهزة", "تحديد متطلبات الموقع (كهرباء، غازات، تبريد، حماية إشعاعية) وإحالتها للمشاريع/الصيانة", "متابعة التوريد والتركيب مع الموردين", "التنسيق مع الصيانة الطبية للاستلام والتدريب"]'::jsonb,6) on conflict (code) do nothing;
insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('GEN','قسم الخدمات العامة','الخدمات العامة','unit','5F7A5B','الخدمات المساندة للتشغيل: النظافة، النقل، الأمن والسلامة، إدارة النفايات، التغذية، الاتصالات الإدارية مع مشغلي الخدمات.','["عقود النظافة والنفايات ومكافحة الحشرات والنقل", "تهيئة المواقع قبل وبعد أعمال المشاريع والصيانة (نظافة، حواجز، تنظيم حركة)", "الأمن والسلامة وتنظيم الدخول لمواقع العمل", "الأثاث غير الطبي والتجهيزات العامة"]'::jsonb,7) on conflict (code) do nothing;
insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('IT','قسم تقنية المعلومات','تقنية المعلومات','unit','1B6CA8','البنية التحتية التقنية والشبكات والأنظمة وأجهزة الحاسب داخل المنشآت.','["مواصفات الشبكات والتيار الخفيف التقني في المشاريع واستلامها", "الأنظمة والتطبيقات وأجهزة الحاسب والطابعات", "ربط الأجهزة الطبية بالشبكة والأنظمة (PACS/LIS/HIS)", "الدعم الفني والبلاغات التقنية"]'::jsonb,8) on conflict (code) do nothing;
insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('BEN','المنشأة / الجهة المستفيدة','المنشأة','ext','8A94A0','المستشفى أو المركز صاحب الاحتياج ومستلم الخدمة.','["رفع الاحتياج أو البلاغ عبر القناة الموحدة", "التنسيق التشغيلي أثناء الأعمال (مكافحة العدوى، الإخلاء الجزئي)", "استلام الخدمة وتقييمها"]'::jsonb,9) on conflict (code) do nothing;
insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('PROC','إدارة المشتريات والعقود','المشتريات','ext','8A94A0','الطرح والترسية والتعاقد وأوامر الشراء.','["الطرح والمنافسات وفتح المظاريف", "الترسية والتعاقد وأوامر الشراء"]'::jsonb,10) on conflict (code) do nothing;
insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('FIN','الإدارة المالية','المالية','ext','8A94A0','الارتباط المالي وصرف المستخلصات.','["الارتباط المالي", "صرف المستخلصات والفواتير"]'::jsonb,11) on conflict (code) do nothing;
insert into public.gov_handoffs(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) select * from (values
('BEN','FAC','عند أي احتياج أو بلاغ من المنشأة (قناة واحدة)','طلب/بلاغ موصوف بالموقع والأثر والصور إن أمكن','تسجيل فوري، تصنيف خلال يوم عمل','G-01','لا يُقبل توجيه الاحتياجات مباشرة إلى الأقسام إلا في الطوارئ (G-11).',1),
('FAC','MNT','إذا كان الاحتياج عطلاً أو تدهوراً في نظام قائم بلا تغيير في التصميم أو المساحة','بلاغ صيانة مصنّف بالأولوية مع موقع الأصل','حسب مصفوفة الأولوية: طارئ 2 ساعة، عاجل 24 ساعة، عادي 5 أيام','G-05','',2),
('FAC','PRJ','إذا تحقق أحد معايير التحول إلى مشروع (R-01): تغيير معماري/إنشائي أو تغيير استخدام المساحة، أو تكلفة تقديرية فوق الحد، أو يحتاج تصميماً وطرحاً، أو تعدد تخصصات','طلب دراسة مشروع مع وصف الاحتياج ومبرراته والمخططات المتاحة','تسجيل المشروع خلال يوم عمل، دراسة أولية خلال 10 أيام عمل','G-02','المشاريع تقرر بعد الدراسة: مشروع، أو إعادته كأعمال صيانة/خدمات.',3),
('FAC','BME','إذا كان الاحتياج يخص جهازاً طبياً قائماً','بلاغ عطل جهاز طبي برقم الأصل ودرجة الخطورة','طارئ (جهاز حرج) فوراً، عادي 24 ساعة','G-08','',4),
('FAC','IT','إذا كان الاحتياج تقنياً: شبكة، حاسب، طابعة، نظام، اتصال','بلاغ تقني مصنّف','حسب اتفاقية مستوى الخدمة التقنية','G-09','',5),
('FAC','GEN','إذا كان الاحتياج خدمة عامة: نظافة، أثاث غير طبي، نقل، أمن، نفايات','طلب خدمة','عادي 3 أيام عمل','G-10','',6),
('MED','PRJ','قبل توريد أي جهاز طبي جديد يحتاج متطلبات موقع (كهرباء، تبريد، غازات، حماية إشعاعية، أحمال إنشائية)','بطاقة متطلبات الموقع من الشركة الصانعة (Site requirements) وموعد التوريد المتوقع','قبل التوريد بـ 60 يوماً على الأقل','G-07','إن كانت المتطلبات بسيطة تُنفذ عبر الصيانة لا المشاريع.',7),
('PRJ','MED','عند اكتمال تجهيز موقع الجهاز','محضر جاهزية الموقع (Site readiness) موقّع من المشاريع والصيانة','قبل موعد التوريد','G-07','',8),
('MED','BME','بعد تركيب الجهاز وتشغيله التجريبي من المورد','الجهاز مع وثائق التدريب والضمان وكتيبات التشغيل','خلال أسبوع من التركيب','G-07','لا يدخل الجهاز الخدمة قبل استلام الصيانة الطبية وإدراجه في سجل الأصول.',9),
('PRJ','IT','عند تحديد نطاق أي مشروع يتضمن شبكات أو تيار خفيف تقني أو أنظمة','مخططات النطاق لمراجعة المواصفات التقنية قبل الطرح','قبل إعداد وثائق الطرح','G-09','تقنية المعلومات تعتمد المواصفات وتستلم الأعمال التقنية عند الإنجاز.',10),
('PRJ','GEN','قبل مباشرة أي أعمال داخل منشأة مشغّلة','خطة الأعمال وموعدها ونطاق الحواجز والممرات البديلة','قبل المباشرة بأسبوع','G-10','الخدمات العامة تنظم الحواجز والنظافة وحركة الدخول وتنسق مع مكافحة العدوى.',11),
('PRJ','FAC','عند الاستلام الابتدائي للمشروع','محضر الاستلام، المخططات كما نُفّذ، الضمانات، الكتيبات، قائمة الأصول الجديدة','خلال أسبوعين من الاستلام الابتدائي','G-04','من هذه اللحظة تدخل الأصول سجل المرافق ويبدأ الضمان.',12),
('PRJ','MNT','مع التسليم للمرافق','جداول الصيانة الوقائية الموصى بها من المقاول/المورد وقطع الغيار الاحتياطية','مع محضر الاستلام','G-04','الصيانة تتابع الأعطال خلال الضمان وتطالب المقاول عبر المشاريع.',13),
('MNT','PRJ','عند ظهور عيب خلال فترة الضمان','بلاغ عيب ضمان بالصور وتاريخ الرصد','خلال 3 أيام عمل من الرصد','P-14','المشاريع تُلزم المقاول بالإصلاح خلال المهلة التعاقدية.',14),
('MNT','PRJ','عندما يتكرر العطل أو تتجاوز كلفة الإصلاح 40٪ من قيمة الاستبدال أو ينتهي العمر الافتراضي للنظام','توصية باستبدال/تطوير النظام مع تقرير الحالة','ضمن الخطة السنوية أو عند الحاجة','G-02','يتحول إلى مشروع بعد الدراسة.',15),
('FAC','GEN','عند الانتقال أو إعادة توزيع المساحات','خطة الانتقال والأثاث والنظافة','قبل الانتقال بأسبوعين','G-12','',16),
('BEN','MNT','طوارئ: تسرب، انقطاع كهرباء/تكييف في منطقة حرجة، حريق، توقف مصعد','اتصال مباشر بغرفة الصيانة ثم تسجيل البلاغ لاحقاً','استجابة خلال ساعتين','G-11','يُبلَّغ المرافق والقسم المختص فوراً.',17)
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-01','حدود التحول إلى مشروع','التصنيف','يُعدّ الاحتياج مشروعاً يُحال إلى قسم المشاريع إذا تحقق واحد أو أكثر من المعايير التالية؛ وإلا يُعالج كأعمال صيانة أو خدمات.','["تغيير معماري أو إنشائي أو تغيير في استخدام المساحة", "تكلفة تقديرية تتجاوز 100,000 ر.س (قيمة مقترحة تحتاج اعتماد)", "يحتاج تصميماً ومخططات أو طرحاً تنافسياً", "يتضمن أكثر من تخصص (معماري + كهربائي + ميكانيكي)", "مدة تنفيذ متوقعة تتجاوز 30 يوماً", "يمس اشتراطات الدفاع المدني أو مكافحة العدوى أو الحماية الإشعاعية"]'::jsonb,'FAC','G-02','القيم المالية والزمنية مقترحة وتُضبط بقرار الإدارة.',1) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-02','ما يبقى في نطاق الصيانة','التصنيف','تبقى في نطاق قسم الصيانة الأعمال التي تعيد نظاماً قائماً إلى حالته دون تغيير في التصميم أو السعة أو الاستخدام.','["إصلاح واستبدال المكونات بمثلها", "الصيانة الوقائية الدورية", "الأعمال الصغيرة دون الحد المالي", "تنفيذ متطلبات الموقع البسيطة للأجهزة الطبية (نقطة كهرباء، تثبيت)"]'::jsonb,'MNT','G-05','',2) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-03','الأجهزة الطبية: قبل التوريد وبعده','التكامل','لا يُورَّد جهاز طبي يحتاج متطلبات موقع قبل اعتماد المتطلبات من المشاريع/الصيانة وتجهيزها، ولا يدخل الخدمة قبل استلام الصيانة الطبية وربطه تقنياً عند الحاجة.','["بطاقة متطلبات الموقع قبل 60 يوماً من التوريد", "محضر جاهزية الموقع قبل التوريد", "استلام الصيانة الطبية بعد التشغيل التجريبي والتدريب", "ربط الجهاز بالأنظمة عبر تقنية المعلومات عند الحاجة"]'::jsonb,'MED','G-07','',3) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-04','تقنية المعلومات في المشاريع','التكامل','كل مشروع يتضمن شبكات أو تيار خفيف تقني أو أنظمة يُراجَع نطاقه من تقنية المعلومات قبل الطرح، وتستلم تقنية المعلومات الأعمال التقنية عند الإنجاز.','["مراجعة المواصفات قبل الطرح", "حضور الاختبارات واستلام الشهادات (شبكات)", "إدراج الأجهزة في سجل الأصول التقنية"]'::jsonb,'IT','G-09','',4) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-05','قناة الاستقبال الموحدة','التصنيف','تستقبل المرافق جميع احتياجات المنشآت وتصنّفها خلال يوم عمل؛ لا تُوجَّه الطلبات مباشرة إلى الأقسام إلا في الطوارئ.','["تسجيل فوري ورقم مرجعي", "تصنيف خلال يوم عمل", "إبلاغ المنشأة بالقسم المختص والمهلة"]'::jsonb,'FAC','G-01','',5) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-06','التنسيق التشغيلي أثناء الأعمال','التكامل','لا تبدأ أعمال داخل منطقة مشغّلة قبل خطة تنسيق تشمل مكافحة العدوى (ICRA) والحواجز وحركة المرضى وأوقات العمل.','["خطة قبل المباشرة بأسبوع", "موافقة مكافحة العدوى", "تهيئة الموقع من الخدمات العامة", "تبليغ المنشأة والأمن"]'::jsonb,'PRJ','G-10','',6) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-07','التسليم للتشغيل والضمان','التكامل','يُسلَّم المشروع للمرافق والصيانة (وتقنية المعلومات والصيانة الطبية بحسب النطاق) بمحضر ووثائق كاملة؛ عيوب الضمان تُبلَّغ من الصيانة وتُطالِب بها المشاريع.','["محضر استلام ابتدائي", "مخططات كما نُفّذ وضمانات وكتيبات", "تحديث سجل الأصول", "جولة فحص قبل انتهاء الضمان"]'::jsonb,'PRJ','G-04','',7) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-08','حدود الاعتماد المالي والزمني','الصلاحيات','أوامر التغيير والتمديد ضمن الحدود الداخلية يعتمدها مدير الإدارة، وفوقها الإدارة التنفيذية ضمن الحد النظامي.','["زيادة حتى 5٪ أو 100,000 ر.س: مدير الإدارة (مقترح)", "فوق ذلك: الإدارة التنفيذية ضمن 10٪ النظامية", "تمديد حتى 30 يوماً أو 10٪ من المدة: مدير الإدارة"]'::jsonb,'DIR','P-08','قيم مقترحة تحتاج اعتماد التجمع.',8) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-09','الطوارئ','التشغيل','في الطوارئ (تسرب، انقطاع في منطقة حرجة، حريق، توقف مصعد) يُتصل بالصيانة مباشرة وتُسجَّل الواقعة لاحقاً، ويُبلَّغ مدير الإدارة خلال ساعة.','["استجابة خلال ساعتين", "تبليغ خلال ساعة", "تقرير واقعة خلال 48 ساعة"]'::jsonb,'MNT','G-11','',9) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-10','تعارض الاختصاص','الصلاحيات','عند الخلاف على القسم المختص يفصل مدير الإدارة خلال يومي عمل، ويُسجَّل القرار كسابقة في القواعد.','["رفع الخلاف من المرافق", "قرار خلال يومي عمل", "تحديث القواعد"]'::jsonb,'DIR','','',10) on conflict (code) do nothing;
