('prj','8. التقارير والمنصة','النسخ الاحتياطي وجودة البيانات (فاحص الجودة)','{"DIR": "I", "HEAD": "A", "ENG": "R", "CLERK": "R"}'::jsonb,75)
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('G-01','استقبال الاحتياجات والبلاغات وتصنيفها','FAC','["BEN", "FAC", "PRJ", "MNT", "BME", "IT", "GEN"]'::jsonb,'قناة واحدة لكل احتياج، وتصنيف صحيح خلال يوم عمل يوصل الطلب إلى القسم المختص بمهلة معلومة.','ورود احتياج أو بلاغ من أي منشأة بأي وسيلة.','وصف الاحتياج، الموقع، الصور، الأثر التشغيلي.','طلب مرقّم مصنّف ومُحال، وإشعار للمنشأة بالقسم المختص والمهلة.','نسبة الطلبات المصنّفة خلال يوم عمل ≥ 95٪؛ نسبة إعادة التوجيه بين الأقسام ≤ 10٪.','[{"unit": "BEN", "action": "ترفع المنشأة الاحتياج عبر القناة الموحدة مع الوصف والموقع والصور", "sla": "—", "where": "نموذج الطلب / المنصة", "kind": "step"}, {"unit": "FAC", "action": "تسجيل الطلب برقم مرجعي والتحقق من اكتمال البيانات", "sla": "فوري", "where": "سجل الطلبات", "kind": "step"}, {"unit": "FAC", "action": "تصنيف الطلب: عطل قائم / احتياج جديد / جهاز طبي / تقني / خدمة عامة، وتطبيق معايير R-01", "sla": "يوم عمل", "where": "موجّه الطلبات", "kind": "decision"}, {"unit": "MNT", "action": "عطل قائم بلا تغيير تصميم → بلاغ صيانة بالأولوية (G-05)", "sla": "حسب الأولوية", "where": "بلاغات الصيانة", "kind": "step"}, {"unit": "PRJ", "action": "يحقق معايير المشروع → طلب دراسة مشروع (G-02)", "sla": "يوم عمل", "where": "المنصة ← مشروع جديد", "kind": "step"}, {"unit": "BME", "action": "جهاز طبي قائم → بلاغ صيانة طبية (G-08)", "sla": "حسب الخطورة", "where": "نظام الأجهزة الطبية", "kind": "step"}, {"unit": "IT", "action": "احتياج تقني → بلاغ تقني (G-09)", "sla": "حسب SLA", "where": "نظام الدعم التقني", "kind": "step"}, {"unit": "GEN", "action": "خدمة عامة → طلب خدمة (G-10)", "sla": "3 أيام عمل", "where": "طلبات الخدمات", "kind": "step"}, {"unit": "FAC", "action": "إبلاغ المنشأة بالقسم المختص والمهلة ومتابعة الإغلاق", "sla": "يوم عمل", "where": "سجل الطلبات", "kind": "step"}]'::jsonb,'الطوارئ تتبع G-11 مباشرة ثم تُسجَّل لاحقاً. تعارض الاختصاص يُرفع لمدير الإدارة (R-10).',1) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('G-02','دراسة الاحتياج وتحويله إلى مشروع','PRJ','["FAC", "PRJ", "MNT", "DIR", "EXEC"]'::jsonb,'قرار موثق خلال 10 أيام عمل: مشروع بميزانية تقديرية، أو إعادة الاحتياج كأعمال صيانة/خدمات.','إحالة من المرافق (G-01) أو توصية من الصيانة باستبدال نظام أو توجيه من الإدارة.','طلب الدراسة، زيارة ميدانية، المخططات المعتمدة من المرافق، المرجع الفني للأسعار.','بطاقة مشروع في المنصة بمرحلة دراسة وتقدير، جدول كميات تقديري، توصية معتمدة.','زمن الدراسة ≤ 10 أيام عمل؛ انحراف التقدير عن الترسية ±15٪.','[{"unit": "PRJ", "action": "تسجيل الطلب كمشروع بمرحلة «طلب/فكرة» وتحديد مهندس المشروع", "sla": "يوم عمل", "where": "المشاريع ← مشروع جديد", "kind": "step"}, {"unit": "PRJ", "action": "زيارة ميدانية مع ممثل المنشأة والصيانة لتحديد النطاق وتوثيقه بتقرير", "sla": "5 أيام عمل", "where": "التقارير الفنية ← زيارة", "kind": "step"}, {"unit": "FAC", "action": "تزويد المشاريع بمخططات المنشأة وسجل الأصول في النطاق", "sla": "يومان", "where": "سجل المرافق", "kind": "step"}, {"unit": "PRJ", "action": "إعداد جدول الكميات التقديري (مقطوعية للتأهيل) من المرجع الفني", "sla": "5 أيام عمل", "where": "جداول الكميات", "kind": "step"}, {"unit": "PRJ", "action": "التوصية: مشروع / أعمال صيانة / خدمات، مع الميزانية والمدة والأولوية", "sla": "يوم", "where": "بطاقة المشروع", "kind": "decision"}, {"unit": "MNT", "action": "إن كانت التوصية أعمال صيانة: استلام الطلب وتنفيذه (G-05)", "sla": "حسب الأولوية", "where": "بلاغات الصيانة", "kind": "step"}, {"unit": "DIR", "action": "اعتماد الدراسة والميزانية التقديرية ضمن الصلاحية أو رفعها للإدارة التنفيذية", "sla": "3 أيام عمل", "where": "تغيير المرحلة ← اعتماد", "kind": "step"}, {"unit": "EXEC", "action": "اعتماد ما يتجاوز صلاحية مدير الإدارة وإدراجه في الخطة", "sla": "حسب دورة الاعتماد", "where": "—", "kind": "step"}, {"unit": "PRJ", "action": "نقل المشروع إلى «تصميم ومخططات» ثم الطرح (P-03) وإبلاغ المرافق والمنشأة", "sla": "يوم", "where": "تغيير المرحلة", "kind": "step"}]'::jsonb,'المشروع الذي لا يُسجَّل في المنصة لا يُعد قائماً.',2) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('G-04','استلام المشروع وتسليمه للتشغيل','PRJ','["PRJ", "FAC", "MNT", "IT", "BME", "GEN", "BEN"]'::jsonb,'انتقال منظّم من المشاريع إلى التشغيل بوثائق كاملة وسجل أصول محدّث وبدء ضمان موثق.','إشعار المقاول باكتمال الأعمال وجاهزيتها للاستلام الابتدائي.','الأعمال المكتملة، نتائج الاختبارات، المخططات كما نُفّذ، الضمانات، الكتيبات، قوائم الأصول.','محضر استلام ابتدائي، ملف التسليم، سجل أصول محدّث، جداول صيانة وقائية.','اكتمال ملف التسليم خلال أسبوعين؛ صفر ملاحظات مفتوحة عند بدء التشغيل.','[{"unit": "PRJ", "action": "التحقق من اكتمال الأعمال والاختبارات وتجهيز قائمة الإغلاق (P-13)", "sla": "5 أيام عمل", "where": "قائمة الإغلاق", "kind": "step"}, {"unit": "PRJ", "action": "دعوة لجنة الاستلام: المرافق، الصيانة، تقنية المعلومات (إن وُجد نطاق تقني)، الصيانة الطبية (إن وُجدت أجهزة)، المنشأة", "sla": "قبل الاستلام بـ 3 أيام", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "فحص الأنظمة الميكانيكية والكهربائية وتسجيل الملاحظات", "sla": "يوم الاستلام", "where": "محضر الاستلام", "kind": "step"}, {"unit": "IT", "action": "اختبار الشبكات والأنظمة واستلام شهادات القياس", "sla": "يوم الاستلام", "where": "محضر الاستلام", "kind": "step"}, {"unit": "BME", "action": "التأكد من جاهزية مواقع الأجهزة الطبية وربطها", "sla": "يوم الاستلام", "where": "محضر الاستلام", "kind": "step"}, {"unit": "PRJ", "action": "محضر الاستلام الابتدائي مع الملاحظات ومهلة إنهائها", "sla": "يوم", "where": "المستندات الرسمية", "kind": "step"}, {"unit": "PRJ", "action": "تسليم ملف التسليم: مخططات كما نُفّذ، ضمانات، كتيبات، جداول الصيانة الوقائية، قائمة الأصول", "sla": "أسبوعان", "where": "المستندات", "kind": "step"}, {"unit": "FAC", "action": "تحديث سجل الأصول والمخططات المعتمدة للمنشأة", "sla": "أسبوع", "where": "سجل المرافق", "kind": "step"}, {"unit": "MNT", "action": "إدراج الأنظمة الجديدة في خطة الصيانة الوقائية وتسجيل تاريخ بدء الضمان", "sla": "أسبوع", "where": "خطة PPM", "kind": "step"}, {"unit": "GEN", "action": "التنظيف النهائي وإزالة الحواجز وإعادة الموقع للتشغيل", "sla": "3 أيام", "where": "طلبات الخدمات", "kind": "step"}, {"unit": "BEN", "action": "استلام الموقع للتشغيل وتقييم الخدمة", "sla": "يوم", "where": "نموذج التقييم", "kind": "step"}]'::jsonb,'أي عيب خلال الضمان يُبلَّغ من الصيانة إلى المشاريع (P-14).',3) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('G-05','الصيانة التصحيحية (البلاغات)','MNT','["FAC", "MNT", "BEN", "PRJ"]'::jsonb,'إصلاح الأعطال ضمن مهل الأولوية وتوثيق كل بلاغ على أصل محدد.','بلاغ محال من المرافق أو طارئ مباشر.','البلاغ، رقم الأصل، الأولوية.','أمر عمل مغلق بتقرير إصلاح وتحديث تاريخ الأصل.','الالتزام بالمهل: طارئ ≤ 2 ساعة، عاجل ≤ 24 ساعة، عادي ≤ 5 أيام ≥ 90٪؛ نسبة تكرار العطل خلال 30 يوماً ≤ 5٪.','[{"unit": "MNT", "action": "استلام البلاغ وتأكيد الأولوية وفتح أمر عمل", "sla": "طارئ فوراً، غيره 4 ساعات", "where": "أوامر العمل", "kind": "step"}, {"unit": "MNT", "action": "الكشف الميداني وتحديد السبب والقطع المطلوبة", "sla": "حسب الأولوية", "where": "أمر العمل", "kind": "step"}, {"unit": "MNT", "action": "الإصلاح بالموارد الذاتية أو عبر مقاول الصيانة", "sla": "حسب الأولوية", "where": "أمر العمل", "kind": "step"}, {"unit": "MNT", "action": "إن كان العطل يستدعي تغييراً في التصميم أو يتجاوز حد المشروع → توصية للمشاريع (G-02)", "sla": "يومان", "where": "المنصة", "kind": "decision"}, {"unit": "BEN", "action": "التأكد من الإصلاح وتوقيع الإغلاق", "sla": "يوم", "where": "أمر العمل", "kind": "step"}, {"unit": "MNT", "action": "إغلاق أمر العمل وتحديث سجل الأصل وتقرير التكلفة", "sla": "يوم", "where": "سجل الأصول", "kind": "step"}, {"unit": "FAC", "action": "إغلاق الطلب الأصلي وإبلاغ المنشأة", "sla": "يوم", "where": "سجل الطلبات", "kind": "step"}]'::jsonb,'',4) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('G-06','الصيانة الوقائية المخططة (PPM)','MNT','["MNT", "FAC", "DIR", "BEN"]'::jsonb,'تقليل الأعطال بصيانة دورية موثقة لكل نظام بحسب توصيات الصانع.','الخطة السنوية المعتمدة.','سجل الأصول، توصيات الصانع، عقود الصيانة.','جدول PPM سنوي، تقارير تنفيذ شهرية.','نسبة إنجاز الخطة الشهرية ≥ 90٪.','[{"unit": "MNT", "action": "بناء خطة PPM السنوية لكل منشأة ونظام", "sla": "نوفمبر من كل عام", "where": "خطة PPM", "kind": "step"}, {"unit": "DIR", "action": "اعتماد الخطة والميزانية", "sla": "ديسمبر", "where": "—", "kind": "step"}, {"unit": "FAC", "action": "تنسيق مواعيد التدخل مع المنشآت", "sla": "شهرياً", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "تنفيذ الزيارات وتسجيل القراءات والملاحظات", "sla": "حسب الجدول", "where": "أوامر العمل", "kind": "step"}, {"unit": "MNT", "action": "رصد الأنظمة المتدهورة والتوصية بالاستبدال (G-02)", "sla": "ربع سنوي", "where": "تقرير الحالة", "kind": "decision"}, {"unit": "DIR", "action": "مراجعة تقرير الإنجاز الشهري", "sla": "شهرياً", "where": "التقارير", "kind": "step"}]'::jsonb,'',5) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('G-07','تجهيز موقع جهاز طبي جديد واستلامه','MED','["MED", "PRJ", "MNT", "IT", "BME", "BEN"]'::jsonb,'ألا يصل جهاز طبي إلى موقع غير مهيأ، وألا يدخل الخدمة قبل استلامه فنياً.','اعتماد توفير جهاز طبي يحتاج متطلبات موقع.','مواصفات الجهاز ومتطلبات الموقع من الصانع، موعد التوريد.','محضر جاهزية الموقع، محضر تركيب وتشغيل تجريبي، إدراج الجهاز في سجل الأصول.','صفر تأخير توريد بسبب الموقع؛ الاستلام خلال أسبوع من التركيب.','[{"unit": "MED", "action": "إرسال بطاقة متطلبات الموقع (كهرباء، تبريد، غازات، أحمال، حماية إشعاعية، شبكة) مع موعد التوريد", "sla": "قبل التوريد بـ 60 يوماً", "where": "نموذج متطلبات الموقع", "kind": "step"}, {"unit": "PRJ", "action": "تقييم المتطلبات: بسيطة → الصيانة، تتطلب أعمالاً إنشائية/كهربائية كبيرة → مشروع مصغّر", "sla": "5 أيام عمل", "where": "المنصة", "kind": "decision"}, {"unit": "MNT", "action": "تنفيذ المتطلبات البسيطة (نقاط كهرباء، تثبيت، تهوية)", "sla": "حسب الحجم", "where": "أوامر العمل", "kind": "step"}, {"unit": "PRJ", "action": "تنفيذ الأعمال الكبيرة والإشراف عليها", "sla": "حسب الجدول", "where": "المشروع", "kind": "step"}, {"unit": "IT", "action": "تجهيز نقاط الشبكة والربط بالأنظمة", "sla": "قبل التوريد", "where": "—", "kind": "step"}, {"unit": "PRJ", "action": "محضر جاهزية الموقع موقّع من المشاريع والصيانة وتقنية المعلومات", "sla": "قبل التوريد بأسبوع", "where": "المستندات", "kind": "step"}, {"unit": "MED", "action": "متابعة التوريد والتركيب والتشغيل التجريبي والتدريب من المورد", "sla": "موعد التوريد", "where": "—", "kind": "step"}, {"unit": "BME", "action": "استلام الجهاز بعد التشغيل التجريبي والتحقق من الوثائق والضمان وإدراجه في سجل الأصول", "sla": "أسبوع", "where": "نظام الأجهزة", "kind": "step"}, {"unit": "BEN", "action": "بدء الاستخدام بعد التدريب", "sla": "—", "where": "—", "kind": "step"}]'::jsonb,'الجهاز الذي لا يمر بالصيانة الطبية لا يدخل الخدمة.',6) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('G-08','أعطال الأجهزة الطبية','BME','["BEN", "FAC", "BME", "MED", "IT"]'::jsonb,'استجابة بحسب خطورة الجهاز وتوثيق العطل والإصلاح في سجل الجهاز.','بلاغ عطل جهاز طبي.','رقم الأصل، درجة الخطورة، وصف العطل.','أمر عمل مغلق، تقرير إصلاح، تحديث سجل الجهاز.','الاستجابة: حرج فوراً، عالٍ 4 ساعات، عادي 24 ساعة ≥ 90٪؛ زمن التوقف للأجهزة الحرجة.','[{"unit": "BEN", "action": "إبلاغ العطل مع رقم الأصل ودرجة الخطورة (حرج/عالٍ/عادي)", "sla": "فوري", "where": "القناة الموحدة", "kind": "step"}, {"unit": "BME", "action": "الاستجابة والكشف وتحديد الإصلاح الذاتي أو عبر الوكيل", "sla": "حسب الخطورة", "where": "أمر العمل", "kind": "step"}, {"unit": "IT", "action": "إن كان العطل في الربط أو النظام → معالجة تقنية", "sla": "حسب SLA", "where": "—", "kind": "step"}, {"unit": "BME", "action": "الإصلاح أو توفير جهاز بديل مؤقت", "sla": "حسب العقد", "where": "—", "kind": "step"}, {"unit": "BME", "action": "إن تجاوزت كلفة الإصلاح 40٪ من القيمة أو انتهى العمر الافتراضي → توصية استبدال للتجهيزات الطبية", "sla": "يومان", "where": "تقرير الحالة", "kind": "decision"}, {"unit": "MED", "action": "دراسة توصية الاستبدال وإدراجها في الخطة", "sla": "شهر", "where": "الخطة", "kind": "step"}, {"unit": "BME", "action": "إغلاق أمر العمل وتحديث سجل الجهاز", "sla": "يوم", "where": "نظام الأجهزة", "kind": "step"}]'::jsonb,'',7) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('G-09','المتطلبات التقنية في المشاريع والطلبات التقنية','IT','["PRJ", "IT", "FAC", "BEN"]'::jsonb,'نطاق تقني صحيح منذ التصميم واستلام موثق للأعمال التقنية.','مشروع يتضمن شبكات/أنظمة، أو طلب تقني من منشأة.','مخططات النطاق، معايير الشبكة المعتمدة.','مواصفات تقنية معتمدة، شهادات قياس، أصول تقنية مسجلة.','صفر مشاريع تُستلم بشبكة غير معتمدة.','[{"unit": "PRJ", "action": "إرسال مخططات النطاق التقني (شبكة، تيار خفيف، أنظمة) قبل إعداد وثائق الطرح", "sla": "قبل الطرح", "where": "المنصة ← المخططات", "kind": "step"}, {"unit": "IT", "action": "مراجعة واعتماد المواصفات أو تعديلها", "sla": "5 أيام عمل", "where": "—", "kind": "step"}, {"unit": "PRJ", "action": "إدراج المواصفات المعتمدة في وثائق الطرح والإشراف على تنفيذها", "sla": "—", "where": "جداول الكميات", "kind": "step"}, {"unit": "IT", "action": "حضور الاختبارات واستلام شهادات القياس والتوثيق", "sla": "عند الإنجاز", "where": "محضر الاستلام", "kind": "step"}, {"unit": "IT", "action": "تسجيل الأصول التقنية وتفعيل الخدمة", "sla": "أسبوع", "where": "سجل الأصول التقنية", "kind": "step"}, {"unit": "IT", "action": "الطلبات التقنية العادية من المنشآت تُعالج عبر نظام الدعم التقني بحسب SLA", "sla": "حسب SLA", "where": "نظام الدعم", "kind": "step"}]'::jsonb,'',8) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('G-10','تهيئة المواقع والخدمات العامة أثناء الأعمال','GEN','["PRJ", "MNT", "GEN", "BEN", "FAC"]'::jsonb,'أعمال داخل منشآت مشغّلة بلا أثر على المرضى والتشغيل.','خطة مباشرة أعمال من المشاريع أو الصيانة داخل منطقة مشغّلة.','خطة الأعمال والمدة والنطاق، موافقة مكافحة العدوى.','موقع مهيأ ومحاط بالحواجز، تنظيف يومي ونهائي، تنظيم دخول.','صفر شكاوى تشغيلية بسبب الأعمال.','[{"unit": "PRJ", "action": "إبلاغ الخدمات العامة والمنشأة بخطة الأعمال قبل المباشرة", "sla": "قبل أسبوع", "where": "المنصة ← المستندات", "kind": "step"}, {"unit": "BEN", "action": "موافقة مكافحة العدوى وتحديد مسارات المرضى البديلة", "sla": "3 أيام", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "تركيب الحواجز واللوحات التحذيرية وتنظيم الدخول والأمن", "sla": "قبل المباشرة", "where": "طلبات الخدمات", "kind": "step"}, {"unit": "GEN", "action": "النظافة الدورية وإدارة المخلفات أثناء الأعمال", "sla": "يومياً", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "التنظيف النهائي وإزالة الحواجز عند الانتهاء", "sla": "3 أيام", "where": "—", "kind": "step"}, {"unit": "FAC", "action": "التأكد من إعادة الموقع للتشغيل وإغلاق الطلب", "sla": "يوم", "where": "سجل الطلبات", "kind": "step"}]'::jsonb,'يُنسَّق العمل المسائي حيث يلزم.',9) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('G-11','الطوارئ في المرافق','MNT','["BEN", "MNT", "FAC", "DIR", "GEN", "IT"]'::jsonb,'احتواء الحدث خلال ساعتين وتوثيقه خلال 48 ساعة.','تسرب، انقطاع كهرباء/تكييف في منطقة حرجة، حريق، توقف مصعد، انهيار جزئي.','اتصال مباشر من المنشأة.','استجابة فورية، تقرير واقعة، إجراءات تصحيحية.','الاستجابة ≤ ساعتين 100٪؛ تقرير خلال 48 ساعة.','[{"unit": "BEN", "action": "الاتصال المباشر بغرفة الصيانة/الأمن", "sla": "فوري", "where": "الهاتف", "kind": "step"}, {"unit": "MNT", "action": "الاستجابة الفورية والاحتواء وعزل الخطر", "sla": "ساعتان", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "إبلاغ المرافق ومدير الإدارة", "sla": "ساعة", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "تأمين الموقع وتنظيم الإخلاء الجزئي إن لزم", "sla": "فوري", "where": "—", "kind": "step"}, {"unit": "IT", "action": "حماية الأنظمة والأجهزة التقنية في المنطقة المتأثرة", "sla": "فوري", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "تسجيل البلاغ لاحقاً وتقرير الواقعة بالأسباب والإجراءات", "sla": "48 ساعة", "where": "أوامر العمل", "kind": "step"}, {"unit": "DIR", "action": "مراجعة التقرير وتوجيه الإجراءات التصحيحية (صيانة/مشروع)", "sla": "3 أيام", "where": "—", "kind": "decision"}]'::jsonb,'',10) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('G-12','إدارة التغيير في المساحات (الانتقال وإعادة التوزيع)','FAC','["BEN", "FAC", "PRJ", "MNT", "GEN", "IT", "MED"]'::jsonb,'أي تغيير في استخدام المساحات يمر بتقييم موحد يحفظ السلامة والاشتراطات.','طلب منشأة لنقل قسم أو إعادة توزيع مساحة.','الطلب، المخططات المعتمدة، الاشتراطات.','خطة انتقال معتمدة، مخططات محدّثة.','تنفيذ الانتقال في موعده بلا توقف خدمة.','[{"unit": "BEN", "action": "طلب التغيير مع المبررات والمساحة المطلوبة", "sla": "—", "where": "القناة الموحدة", "kind": "step"}, {"unit": "FAC", "action": "تقييم الملاءمة مع المخططات والاشتراطات وتحديد الأعمال اللازمة", "sla": "5 أيام عمل", "where": "سجل المرافق", "kind": "decision"}, {"unit": "PRJ", "action": "إن تطلب أعمالاً إنشائية → مشروع (G-02)", "sla": "—", "where": "المنصة", "kind": "step"}, {"unit": "MNT", "action": "الأعمال الفنية البسيطة (كهرباء، تكييف)", "sla": "حسب الحجم", "where": "أوامر العمل", "kind": "step"}, {"unit": "IT", "action": "نقل/تمديد الشبكة والأجهزة التقنية", "sla": "قبل الانتقال", "where": "—", "kind": "step"}, {"unit": "MED", "action": "نقل الأجهزة الطبية بالتنسيق مع الصيانة الطبية", "sla": "قبل الانتقال", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "الأثاث والنظافة والنقل", "sla": "موعد الانتقال", "where": "طلبات الخدمات", "kind": "step"}, {"unit": "FAC", "action": "تحديث المخططات المعتمدة وسجل المساحات", "sla": "أسبوع", "where": "سجل المرافق", "kind": "step"}]'::jsonb,'',11) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-01','تسجيل مشروع جديد ودراسته','PRJ','["DIR", "PRJ"]'::jsonb,'أن يُسجَّل كل احتياج يصل للقسم كمشروع في المنصة خلال يوم عمل، وأن تكتمل دراسته الأولية بميزانية تقديرية موثقة.','ورود طلب من منشأة/إدارة، أو توجيه من الإدارة، أو رصد احتياج ميداني.','خطاب/طلب الجهة المستفيدة، الزيارة الميدانية، المرجع الفني للبنود والأسعار.','بطاقة المشروع في المنصة بمرحلة «طلب/فكرة» ثم «دراسة وتقدير»، جدول كميات تقديري، ملخص الدراسة.','نسبة الطلبات المسجلة خلال يوم عمل؛ زمن إكمال الدراسة (المستهدف 10 أيام عمل للمشاريع المتوسطة).','[{"unit": "PRJ", "role": "رئيس القسم", "action": "يستلم الطلب ويحدد مهندس المشروع بحسب التخصص والعبء (عدد المشاريع القائمة لكل مهندس)", "sla": "يوم عمل", "where": "المشاريع ← مشروع جديد", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "يسجّل المشروع: الاسم، الفئة، النوع، المنشأة، الجهة المستفيدة، الأولوية، البرنامج المالي، وصف الاحتياج", "sla": "يوم عمل", "where": "بطاقة المشروع", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "زيارة ميدانية لتحديد النطاق، وتوثيقها بتقرير زيارة مع الصور", "sla": "5 أيام عمل", "where": "التقارير الفنية ← زيارة", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "إعداد جدول الكميات التقديري من المرجع الفني (P-02)", "sla": "5 أيام عمل", "where": "المالية ← جداول الكميات", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "مراجعة الدراسة والنطاق والميزانية، ونقل المشروع إلى «دراسة وتقدير» ثم «اعتماد» أو إعادته", "sla": "3 أيام عمل", "where": "تغيير المرحلة", "kind": "step"}, {"unit": "DIR", "role": "مدير الإدارة", "action": "اعتماد الميزانية التقديرية ورفع المشروع للإدراج في الخطة", "sla": "بحسب دورة الميزانية", "where": "الطلبات ← قرار", "kind": "step"}]'::jsonb,'المشروع الذي لا يُسجَّل في المنصة لا يُعد قائماً ولا يُتابع. يُحدَّد لكل مشروع مهندس واحد مسؤول حتى لو شارك فيه آخرون.','1.0',100) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-02','إعداد جدول الكميات التقديري واعتماده','PRJ','["PRJ"]'::jsonb,'ميزانية تقديرية موحدة الأساس لكل المشاريع باستخدام المرجع الفني للبنود والأسعار، قابلة للمقارنة والمراجعة.','اكتمال تحديد النطاق في P-01، أو طلب تحديث الأسعار قبل الطرح.','النطاق والمخططات الأولية، المرجع الفني، عروض أسعار استرشادية عند الحاجة.','جدول كميات معتمد في المنصة (إصدار مرقّم) بإجمالي يشمل الاحتياطي والضريبة، ملف Excel/PDF للمعاملة.','انحراف الميزانية التقديرية عن قيمة الترسية (المستهدف ±15%).','[{"unit": "PRJ", "role": "مهندس المشروع", "action": "إنشاء جدول كميات جديد للمشروع باسم واضح (تقديري/إصدار 2…) وضبط الاحتياطي والضريبة", "sla": "يوم", "where": "ملخص المشروع ← جداول الكميات ← جديد", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "اختيار البنود من المرجع الفني وإدخال الكميات والمواقع؛ البنود غير الموجودة تُضاف كبنود حرة مع ذكر مصدر السعر", "sla": "3–5 أيام", "where": "محرر جدول الكميات", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "تحديث الأسعار من المرجع قبل الرفع، ومراجعة الإجمالي", "sla": "يوم", "where": "تحديث الأسعار", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "مراجعة الكميات والبنود والحالة، وتغيير حالة الجدول إلى «معتمد» أو إعادته بملاحظات", "sla": "3 أيام عمل", "where": "إعدادات الجدول", "kind": "step"}, {"unit": "PRJ", "role": "المنسق الإداري", "action": "طباعة الجدول المعتمد وإرفاقه بمعاملة الاعتماد/الطرح وتسجيله في المستندات", "sla": "يوم", "where": "تصدير Excel / طباعة", "kind": "step"}]'::jsonb,'لا يُعدَّل الجدول المعتمد؛ أي تغيير يكون بإصدار جديد مع الاحتفاظ بالقديم للمقارنة.','1.0',101) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-03','التصميم والطرح والتعاقد','PRJ','["PRJ"]'::jsonb,'وثائق طرح مكتملة تقلل الاستفسارات وأوامر التغيير لاحقاً، وانتقال سلس من الترسية إلى المباشرة.','اعتماد المشروع وإدراجه في الخطة.','الدراسة المعتمدة، جدول الكميات، المخططات والمواصفات، نماذج المشتريات.','كراسة الشروط والمواصفات، مخططات الطرح، محضر الترسية، العقد وملاحقه مسجلة في المنصة، تواريخ الطرح/الترسية/المباشرة محدثة.','عدد الاستفسارات والتعديلات أثناء الطرح؛ المدة من الاعتماد إلى الترسية.','[{"unit": "PRJ", "role": "مهندس المشروع", "action": "إعداد المخططات والمواصفات ونطاق العمل النهائي ورفعها في المخططات (مراجعة 0)", "sla": "بحسب حجم المشروع", "where": "المستندات ← المخططات", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "مراجعة الوثائق الفنية واعتمادها ونقل المشروع إلى «تصميم ومخططات» ثم «طرح»", "sla": "5 أيام عمل", "where": "تغيير المرحلة", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "تسليم وثائق الطرح للمشتريات، والرد على الاستفسارات الفنية للمتنافسين كتابةً عبر المشتريات", "sla": "بحسب جدول المنافسة", "where": "المستندات ← خطابات", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "المشاركة في الفحص الفني للعروض عند التكليف، وتوثيق التوصية", "sla": "بحسب اللجنة", "where": "الطلبات/المستندات", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "بعد الترسية: تسجيل بيانات العقد (المقاول، القيمة، المدة، التواريخ) ورفع نسخة العقد والضمان البنكي ووثيقة التأمين", "sla": "3 أيام عمل من استلام العقد", "where": "تعديل البيانات + المستندات", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "نقل المشروع إلى «ترسية وتعاقد» ثم «تنفيذ» عند تسليم الموقع", "sla": "يوم", "where": "تغيير المرحلة", "kind": "step"}]'::jsonb,'','1.0',102) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-04','المباشرة وبناء الجدول الزمني والخط الأساس','PRJ','["PRJ"]'::jsonb,'أن يبدأ كل مشروع تنفيذ بجدول زمني مطابق للبرنامج المعتمد للمقاول وخط أساس معتمد يُقاس عليه الانحراف.','تسليم الموقع/المباشرة الفعلية.','البرنامج الزمني للمقاول، العقد ومدته، تاريخ المباشرة.','محضر تسليم الموقع مسجل، حزم أعمال بأوزان مجموعها 100%، معالم رئيسية، خط أساس معتمد.','نسبة مشاريع التنفيذ ذات خط أساس معتمد خلال 15 يوماً من المباشرة (المستهدف 100%).','[{"unit": "PRJ", "role": "مهندس المشروع", "action": "توثيق محضر تسليم الموقع وتاريخ المباشرة وتحديث تاريخ الانتهاء التعاقدي", "sla": "يوم", "where": "المستندات ← تسليم موقع + تعديل البيانات", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "استلام البرنامج الزمني من المقاول ومراجعته (التسلسل، المسار الحرج، التوريدات الطويلة)", "sla": "10 أيام", "where": "—", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "بناء الجدول في المنصة: قالب جاهز أو لصق من Excel، ثم مطابقة الحزم والأوزان والتواريخ والمعالم", "sla": "3 أيام", "where": "المتابعة ← الجدول الزمني", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "مراجعة الجدول واعتماد الخط الأساس (تُقفل التواريخ المخططة بعدها)", "sla": "3 أيام عمل", "where": "اعتماد الخط الأساس", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "إبقاء «مصدر نسبة الإنجاز» يدوياً حتى اكتمال شهرين من التحديث المنتظم، ثم التحويل إلى الجدول بموافقة رئيس القسم", "sla": "شهران", "where": "مصدر نسبة الإنجاز", "kind": "step"}]'::jsonb,'تعديل التواريخ المخططة بعد اعتماد الخط الأساس لا يكون إلا بأمر تمديد معتمد (P-08) عبر «إزاحة الجدول»، مع بقاء الأساس للمقارنة.','1.0',103) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-05','المتابعة الدورية للتنفيذ','PRJ','["PRJ"]'::jsonb,'أن تعكس المنصة الحالة الفعلية لكل مشروع بفارق لا يتجاوز أسبوعاً، وأن يُكتشف التأخر قبل أن يتحول إلى تعثر.','دوري: أسبوعي وشهري، وعند أي حدث مؤثر.','الزيارات الميدانية، تقارير المقاول، اجتماعات الموقع.','تحديثات المشروع، تقارير الزيارات، نسب الإنجاز والحزم، المعالم المتحققة، التحديات المرصودة.','مؤشر التغطية (لا مشروع بلا تحديث 14 يوماً)؛ الالتزام بالمواعيد؛ سرعة الاستجابة — كما تحسبها المنصة في «الأداء والإنجازات».','[{"unit": "PRJ", "role": "مهندس المشروع", "action": "زيارة ميدانية أسبوعية على الأقل لمشاريع التنفيذ، وتوثيقها بتقرير زيارة بالصور خلال 24 ساعة", "sla": "أسبوعي", "where": "التقارير الفنية ← زيارة", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "تحديث نسب حزم الأعمال وتحقق المعالم، وتسجيل تحديث موجز بالمستجدات", "sla": "أسبوعي", "where": "الجدول الزمني + التحديثات", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "تقرير حالة شهري يتضمن الإنجاز مقابل المخطط، الانحراف، الأسباب، الإجراءات، والصرف", "sla": "أول 5 أيام من كل شهر", "where": "التقارير الفنية ← شهري", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "مراجعة التقارير المنشورة وتحويلها إلى «تمت مراجعته» أو إعادتها بملاحظات، وتحويل القرارات إلى مهام", "sla": "3 أيام عمل", "where": "مراجعة التقرير", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "متابعة مؤشرات «بلا تحديث» و«متأخر» في لوحة المؤشرات وصفحة «يومي» والتصعيد عند الحاجة", "sla": "يومي", "where": "لوحة المؤشرات / يومي", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "أي حدث مؤثر (إيقاف، حادثة، تعثر) يُسجَّل خلال 24 ساعة كتقرير حادثة/حالة ويُبلَّغ رئيس القسم مباشرة", "sla": "24 ساعة", "where": "التقارير الفنية ← حادثة", "kind": "step"}]'::jsonb,'','1.0',104) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-06','الاعتمادات (العينات والمواد ومخططات الورشة)','PRJ','["PRJ"]'::jsonb,'قرار اعتماد موثق خلال المهلة المحددة (7 أيام) بلا تأخير على المقاول ولا تجاوز للمواصفات.','تقديم المقاول طلب اعتماد.','طلب الاعتماد ومرفقاته، المواصفة المرجعية أو بند جدول الكميات، كتالوجات وشهادات.','سجل اعتماد برقم تسلسلي ومراجعات (R1, R2…)، توصية المهندس، قرار الإدارة (A معتمد / B معتمد بملاحظات / C يُعاد التقديم / D مرفوض).','نسبة الاعتمادات المقررة خلال المهلة (المستهدف ≥ 90%)؛ عدد الإعادات لكل اعتماد.','[{"unit": "PRJ", "role": "المنسق الإداري / المهندس", "action": "تسجيل طلب الاعتماد في المنصة مع ربطه ببند جدول الكميات أو المواصفة المرجعية ورفع المرفقات", "sla": "يوم من الاستلام", "where": "المستندات ← الاعتمادات ← جديد", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "المراجعة الفنية: المطابقة للمواصفة، الشهادات، العينة الفعلية عند الحاجة، وكتابة التوصية", "sla": "4 أيام", "where": "مراجعة المهندس", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "القرار A/B/C/D مع الملاحظات", "sla": "خلال 7 أيام من التسجيل", "where": "قرار الإدارة", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "إذا كان البديل يمس المواصفة جوهرياً أو له أثر مالي/زمني: يُرفع لمدير الإدارة قبل القرار", "sla": "ضمن المهلة", "where": "الطلبات ← قرار", "kind": "step"}, {"unit": "PRJ", "role": "المنسق الإداري", "action": "إبلاغ المقاول بالقرار كتابةً وأرشفة الخطاب", "sla": "يوم", "where": "المستندات ← خطاب صادر", "kind": "step"}]'::jsonb,'الاعتماد لا يُعفي المقاول من مسؤوليته التعاقدية عن مطابقة الأعمال. المهلة تُضبط من إعدادات المنصة (submittal_sla_days).','1.0',105) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-07','المستخلصات المالية','PRJ','["DIR", "PRJ"]'::jsonb,'مستخلص مدقق فنياً بحسب الأعمال المنفذة فعلاً، معتمد ومحال للصرف ضمن المهل، مع تتبع كامل للمصروف والمحتجز.','تقديم المقاول مستخلصاً دورياً أو ختامياً.','مستخلص المقاول، حصر الكميات المنفذة، نسب الإنجاز، خصومات/غرامات إن وجدت، المستخلصات السابقة.','سجل مستخلص برقم تسلسلي وحالة (مقدَّم ← مراجعة ← معتمد ← محال للمالية ← مصروف)، محضر تدقيق، صافي المستحق والمحتجز التراكمي.','المدة من تقديم المستخلص إلى الإحالة (المستهدف ≤ 10 أيام عمل)؛ فروقات التدقيق.','[{"unit": "PRJ", "role": "مهندس المشروع", "action": "استلام المستخلص وتدقيق الكميات ميدانياً ومطابقتها لنسب الحزم في الجدول الزمني", "sla": "5 أيام عمل", "where": "المالية ← المستخلصات ← جديد", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "تسجيل المستخلص في المنصة: الأعمال المنفذة تراكمياً، المحتجز، الخصومات، الغرامات، صافي المستحق، والتقدّم بالحالة «مقدَّم»", "sla": "ضمن المدة", "where": "نموذج المستخلص", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "المراجعة الفنية والمطابقة مع نسبة الإنجاز والصرف التراكمي، ثم «معتمد» أو الإعادة", "sla": "3 أيام عمل", "where": "مراجعة/اعتماد", "kind": "step"}, {"unit": "DIR", "role": "مدير الإدارة", "action": "الاعتماد الإداري والإحالة إلى الإدارة المالية بخطاب", "sla": "2 يوم عمل", "where": "إحالة للمالية + خطاب صادر", "kind": "step"}, {"unit": "PRJ", "role": "المنسق الإداري", "action": "متابعة الصرف مع المالية وتسجيل تاريخ الصرف الفعلي والمبلغ", "sla": "عند الصرف", "where": "تسجيل الصرف", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "مراقبة مؤشر «الصرف مقابل الإنجاز»: صرف يسبق الإنجاز بأكثر من 10 نقاط يستوجب مراجعة", "sla": "شهري", "where": "لوحة المؤشرات", "kind": "step"}]'::jsonb,'لا يُقبل مستخلص لأعمال غير معتمدة اعتماداتها (P-06) أو لبنود خارج العقد بلا أمر تغيير معتمد (P-08).','1.0',106) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-08','أوامر التغيير والتمديدات','PRJ','["DIR", "PRJ"]'::jsonb,'ضبط أي تغيير في القيمة أو المدة بقرار موثق قبل التنفيذ، ومزامنة قيمة العقد ومدته تلقائياً في المنصة.','الحاجة لأعمال إضافية/حذف أعمال، أو طلب المقاول تمديداً بأسباب مبررة.','المبررات الفنية، تسعير الأعمال من المرجع أو العقد، أثر التغيير على الجدول، طلب المقاول.','أمر تغيير مرقّم (مالي/زمني/كلاهما) بحالة مسودة ← مقدَّم ← معتمد/مرفوض، تحديث تلقائي لقيمة العقد وتاريخ الانتهاء المعدل، إزاحة الجدول الزمني.','نسبة أوامر التغيير التراكمية لقيمة العقد (المستهدف ≤ 5%)؛ التمديدات التراكمية لمدة العقد.','[{"unit": "PRJ", "role": "مهندس المشروع", "action": "تحليل الطلب: هل هو ضمن نطاق العقد؟ ما أثره المالي والزمني؟ هل يوجد بديل؟", "sla": "5 أيام", "where": "—", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "تسجيل أمر التغيير في المنصة بالنوع والقيمة (موجبة/سالبة) والأيام والمبررات والمرفقات، وتقديمه", "sla": "يوم", "where": "المالية ← أوامر التغيير", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "المراجعة والتوصية، وتحديد جهة الاعتماد بحسب الحدود التراكمية", "sla": "3 أيام عمل", "where": "مراجعة", "kind": "step"}, {"unit": "DIR", "role": "مدير الإدارة / الإدارة التنفيذية", "action": "القرار (اعتماد/رفض) ضمن الصلاحية", "sla": "5 أيام عمل", "where": "قرار أمر التغيير", "kind": "step"}, {"unit": "PRJ", "role": "المنصة (تلقائي)", "action": "عند الاعتماد: تحديث قيمة العقد الإجمالية وتاريخ الانتهاء المعدل، وإشعار المعنيين", "sla": "فوري", "where": "مزامنة العقد", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "إزاحة الجدول الزمني بعدد أيام التمديد وإبلاغ المقاول كتابةً، وربط التحدي المسبب إن وجد", "sla": "3 أيام", "where": "الجدول الزمني ← إزاحة", "kind": "step"}]'::jsonb,'لا تُنفَّذ أعمال إضافية قبل اعتماد أمر التغيير إلا في حالات السلامة الطارئة بموافقة مدير الإدارة الشفهية الموثقة لاحقاً خلال 48 ساعة.','1.0',107) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-09','إدارة التحديات والمخاطر','PRJ','["PRJ"]'::jsonb,'أن يتحول كل تحدٍ إلى عمل له صاحب وموعد، وألا يبقى تحدٍ بدرجة عالية بلا مهام معالجة.','رصد أي أمر قد يؤثر على المدة أو التكلفة أو الجودة أو السلامة.','الملاحظة الميدانية، مراسلات المقاول، تقارير الحالة.','سجل تحدٍ بدرجة (الأثر × الاحتمالية)، خطة معالجة، مهام مرتبطة، سجل متابعة، إغلاق بسبب موثق.','عدد التحديات المفتوحة بدرجة عالية بلا مهام (المستهدف صفر)؛ متوسط عمر التحدي حتى الإغلاق.','[{"unit": "PRJ", "role": "مهندس المشروع", "action": "تسجيل التحدي فور رصده: الوصف، التصنيف، الأثر، الاحتمالية، الأثر الزمني والمالي المتوقع، الموعد المستهدف، خطة المعالجة المقترحة", "sla": "48 ساعة", "where": "المتابعة ← التحديات ← جديد", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "مراجعة الدرجة، وتكليف مهام المعالجة من داخل ملف التحدي، أو رفعه لمدير الإدارة إذا تجاوز صلاحيته", "sla": "3 أيام عمل", "where": "ملف التحدي ← مهمة من التحدي", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "تسجيل متابعة أسبوعية في سجل التحدي (ما تم، وما التالي) حتى الإغلاق", "sla": "أسبوعي", "where": "سجل المتابعة", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "إغلاق التحدي بعد إنجاز مهامه بسبب: تمت المعالجة / تحوّل لأمر تغيير / قُبل كمخاطرة / ملغى", "sla": "عند الإنجاز", "where": "إغلاق التحدي", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "إدراج التحديات بدرجة 8 فأكثر في التقرير التنفيذي الأسبوعي تحت «يحتاج انتباهكم»", "sla": "أسبوعي", "where": "التقرير التنفيذي", "kind": "step"}]'::jsonb,'','1.0',108) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-10','المهام والطلبات والتصعيد','PRJ','["PRJ"]'::jsonb,'قناة واحدة للتكليف من الإدارة إلى المهندسين (المهام) وللطلبات من المهندسين إلى الإدارة (الطلبات)، بمهل واضحة.','قرار اجتماع، توجيه، ملاحظة تقرير، أو حاجة لقرار الإدارة.','القرار أو الحاجة، المشروع المعني، الموعد.','مهمة بحالة (مفتوحة ← قيد التنفيذ ← منجزة) وملاحظة إنجاز؛ طلب بحالة (جديد ← قيد المراجعة ← معتمد/مرفوض/منفذ) ورد الإدارة.','نسبة المهام المنجزة في موعدها؛ زمن الرد على الطلبات (المستهدف 3 أيام عمل).','[{"unit": "PRJ", "role": "رئيس القسم", "action": "إنشاء المهمة بعنوان واضح ومكلَّف وموعد وأولوية، ويُفضَّل من داخل التقرير/المحضر/التحدي حتى تبقى مرتبطة بمصدرها", "sla": "عند القرار", "where": "المهام ← جديد", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "تحديث حالة المهمة وكتابة ملاحظة الإنجاز عند الانتهاء؛ المهمة التي تتعذر تُبلَّغ قبل موعدها لا بعده", "sla": "قبل الموعد", "where": "المهام ← تحديث", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "رفع طلب للإدارة (اعتماد/مراجعة/قرار/دعم) مع التفاصيل والمرفقات والمهلة المطلوبة", "sla": "عند الحاجة", "where": "الطلبات ← جديد", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "الرد على الطلب أو رفعه لمدير الإدارة، وتوثيق الرد", "sla": "3 أيام عمل", "where": "الطلبات ← الرد", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "التصعيد: مهمة متأخرة > 7 أيام أو طلب بلا رد > 5 أيام يُناقش في الاجتماع الأسبوعي ويُوثق قراره", "sla": "أسبوعي", "where": "الاجتماع الأسبوعي", "kind": "step"}]'::jsonb,'','1.0',109) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-11','المراسلات والمستندات الرسمية','PRJ','["PRJ"]'::jsonb,'أن يكون لكل مشروع ملف مستندات كامل في المنصة (عقد، ضمانات، تأمين، خطابات، محاضر) بتواريخ صلاحية مراقبة.','صدور أو ورود أي مستند رسمي.','المستند الأصلي أو نسخته الممسوحة.','سجل مستند مصنف (عقد/تسليم موقع/استلام/ضمان بنكي/تأمين/خطاب وارد/صادر/أمر تغيير/تمديد/محضر) مع الملف وتاريخ الانتهاء أو مهلة الرد.','لا ضمان بنكي أو وثيقة تأمين منتهية لمشروع قائم؛ نسبة الخطابات الواردة المردود عليها في مهلتها.','[{"unit": "PRJ", "role": "المنسق الإداري", "action": "تسجيل المستند في يوم وروده/صدوره مع التصنيف والرقم والتاريخ والجهة والملف، وإدخال تاريخ الانتهاء للضمانات والتأمين ومهلة الرد للخطابات", "sla": "يوم", "where": "المستندات ← الرسمية ← جديد", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "صياغة الخطابات الفنية للمقاول/الاستشاري، وتوقيعها من صاحب الصلاحية (رئيس القسم أو مدير الإدارة بحسب المصفوفة)", "sla": "بحسب المهلة", "where": "خطاب صادر", "kind": "step"}, {"unit": "PRJ", "role": "المنصة (تلقائي)", "action": "تنبيه قبل انتهاء الضمان/التأمين بـ 30 يوماً وعند تجاوز مهلة الرد", "sla": "تلقائي", "where": "الإشعارات / يومي", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "طلب تجديد الضمان أو التأمين من المقاول قبل انتهائه، وتسجيل الجديد وربطه", "sla": "قبل الانتهاء بـ 15 يوماً", "where": "المستندات", "kind": "step"}, {"unit": "PRJ", "role": "المنسق الإداري", "action": "حفظ الأصول الورقية في ملف المشروع بترقيم يطابق المنصة", "sla": "مستمر", "where": "—", "kind": "step"}]'::jsonb,'أسماء الملفات تُرفع كما هي (العربية مدعومة)؛ الحد 50 م.ب للمستند و8 م.ب للصورة. الخطاب الذي لا يُسجَّل في المنصة لا يُحتج به في المتابعة.','1.0',110) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-12','محاضر الاجتماعات والقرارات','PRJ','["PRJ"]'::jsonb,'محضر لكل اجتماع خلال 24 ساعة، وكل قرار فيه يتحول إلى مهمة لها صاحب وموعد.','انعقاد اجتماع موقع أو اجتماع دوري.','جدول الأعمال، الحضور، ما تم مناقشته.','محضر في المنصة بالحضور والبنود والقرارات، ومهام مرتبطة بالمحضر.','نسبة القرارات المحوّلة إلى مهام؛ زمن نشر المحضر.','[{"unit": "PRJ", "role": "مهندس المشروع", "action": "إنشاء محضر اجتماع في المنصة بالتاريخ والحضور والبنود، ولكل قرار: النص والمسؤول والموعد", "sla": "24 ساعة", "where": "التقارير الفنية ← محضر", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "نشر المحضر وإرسال نسخته للمقاول/الاستشاري عبر خطاب أو بريد رسمي", "sla": "24 ساعة", "where": "نشر + خطاب صادر", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "مراجعة المحضر وتحويل القرارات الداخلية إلى مهام من داخله", "sla": "3 أيام عمل", "where": "مراجعة ← مهمة من القرار", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "اجتماع أسبوعي للقسم (30 دقيقة) يُراجع فيه: المتأخر، بلا تحديث، التحديات العالية، الطلبات المعلقة، خطة الأسبوع؛ ويُوثق بمحضر", "sla": "أسبوعي", "where": "لوحة المؤشرات + محضر", "kind": "step"}]'::jsonb,'','1.0',111) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-13','الاستلام الابتدائي وقائمة الإغلاق','PRJ','["PRJ"]'::jsonb,'استلام ابتدائي موثق بلا ملاحظات معلقة، واكتمال متطلبات الإغلاق قبل بدء فترة الضمان.','إخطار المقاول باكتمال الأعمال، أو بلوغ الإنجاز 100%.','إخطار المقاول، الاعتمادات والاختبارات، المخططات كما نُفّذ، الكتيبات وشهادات الضمان.','محضر الاستلام الابتدائي، قائمة الملاحظات ومواعيد إنهائها، قائمة الإغلاق مكتملة في المنصة، تاريخ الاستلام وبدء الضمان.','المدة من إخطار المقاول إلى محضر الاستلام (المستهدف ≤ 15 يوماً)؛ نسبة بنود الإغلاق المكتملة عند نقل المرحلة.','[{"unit": "PRJ", "role": "مهندس المشروع", "action": "فحص أولي للتأكد من اكتمال الأعمال والاختبارات والتشغيل التجريبي قبل طلب اللجنة", "sla": "5 أيام", "where": "التقارير الفنية ← حالة", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "رفع طلب تشكيل لجنة الاستلام لمدير الإدارة مع تاريخ مقترح", "sla": "2 يوم", "where": "الطلبات ← طلب قرار", "kind": "step"}, {"unit": "PRJ", "role": "اللجنة", "action": "الاستلام الميداني وتوثيق الملاحظات بمواعيد إنهاء، وتوقيع المحضر", "sla": "بحسب التكليف", "where": "—", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "تسجيل المحضر وتاريخ الاستلام الابتدائي في المنصة وإكمال قائمة الإغلاق بنداً بنداً (كما نُفّذ، الضمانات، التدريب، الكتيبات، قطع الغيار، الإخلاء)", "sla": "10 أيام", "where": "الإغلاق والضمان", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "نقل المشروع إلى «استلام ابتدائي» (يُعد منتهياً في المؤشرات) بعد التأكد من إغلاق الملاحظات", "sla": "عند الاكتمال", "where": "تغيير المرحلة", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "تسجيل تقييم المقاول والدروس المستفادة", "sla": "10 أيام", "where": "الإغلاق والضمان ← التقييم", "kind": "step"}]'::jsonb,'','1.0',112) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-14','فترة الضمان والاستلام النهائي','PRJ','["PRJ"]'::jsonb,'ألا تنتهي فترة ضمان دون جولة فحص موثقة، وألا يُفرج عن المحتجز قبل استيفاء الالتزامات.','بدء فترة الضمان بعد الاستلام الابتدائي.','محضر الاستلام الابتدائي، مدة الضمان التعاقدية، بلاغات المنشأة عن العيوب.','سجل بلاغات الضمان ومعالجتها، محضر جولة الفحص قبل انتهاء الضمان، محضر الاستلام النهائي، تسجيل الإفراج عن المحتجز، إقفال المشروع.','عدد بلاغات الضمان ومتوسط زمن معالجتها؛ نسبة المشاريع التي أُجريت لها جولة فحص قبل انتهاء الضمان (المستهدف 100%).','[{"unit": "PRJ", "role": "مهندس المشروع", "action": "التأكد من تسجيل تاريخ انتهاء الضمان في المنصة (يُحسب تلقائياً من مدة الضمان)", "sla": "بعد الاستلام", "where": "الإغلاق والضمان", "kind": "step"}, {"unit": "PRJ", "role": "المنسق الإداري", "action": "استقبال بلاغات المنشأة خلال الضمان وتسجيلها كتحديثات وإبلاغ المقاول كتابةً", "sla": "يوم", "where": "التحديثات + خطاب", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "متابعة المقاول في معالجة العيوب وتوثيق الإصلاح", "sla": "بحسب العقد", "where": "التحديثات", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "جولة فحص شاملة قبل انتهاء الضمان بـ 30 يوماً (تنبيه تلقائي) وتوثيق الملاحظات وإلزام المقاول بها", "sla": "قبل 30 يوماً", "where": "التقارير الفنية ← زيارة", "kind": "step"}, {"unit": "PRJ", "role": "مهندس المشروع", "action": "طلب لجنة الاستلام النهائي بعد إغلاق الملاحظات، وتسجيل المحضر وتاريخ الإفراج عن المحتجز", "sla": "عند الانتهاء", "where": "الطلبات + الإغلاق والضمان", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "نقل المشروع إلى «مقفل» وأرشفته", "sla": "بعد الإفراج", "where": "تغيير المرحلة + أرشفة", "kind": "step"}]'::jsonb,'','1.0',113) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-15','التقارير الدورية للإدارة','PRJ','["PRJ"]'::jsonb,'صورة صادقة ومنتظمة للإدارة عن المحفظة بأقل جهد يدوي، من مصدر واحد هو المنصة.','دوري: يومي، أسبوعي، شهري، وعند الطلب.','بيانات المنصة كما هي وقت الإصدار.','ملخص «يومي» (تلقائي)، التقرير التنفيذي الأسبوعي (رابط مجمّد + PDF)، التقرير الشهري، تقارير مخصصة عند الطلب.','انتظام الإصدار الأسبوعي؛ عدد ملاحظات الإدارة التنفيذية المعالجة.','[{"unit": "PRJ", "role": "رئيس القسم", "action": "كل صباح: مراجعة «يومي» ولوحة المؤشرات والتصرف في صندوق الإجراءات", "sla": "يومي", "where": "يومي / لوحة المؤشرات", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "كل خميس: تحديد فترة الأسبوع في التقرير التنفيذي، مراجعة «يحتاج انتباهكم»، ثم «نشر رابط للإدارة» وإرساله لمدير الإدارة والإدارة التنفيذية، مع PDF عند الطلب", "sla": "أسبوعي", "where": "التقارير ← التقرير التنفيذي", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "متابعة ملاحظات الإدارة التنفيذية الواردة عبر الرابط وتحويلها إلى مهام أو ردود خلال يومي عمل", "sla": "يومي عمل", "where": "الروابط المنشورة ← الملاحظات", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "التقرير الشهري (الفترة: الشهر) لمدير الإدارة مع تحليل الانحرافات وخطة الشهر التالي", "sla": "أول 7 أيام من الشهر", "where": "التقارير ← فترة مخصصة", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "إلغاء روابط التقارير المنتهية والاحتفاظ بأرشيف PDF للتقارير الشهرية في ملف القسم", "sla": "شهري", "where": "الروابط المنشورة", "kind": "step"}]'::jsonb,'','1.0',114) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,version,sort) values ('P-16','إدارة المنصة وجودة البيانات','PRJ','["PRJ"]'::jsonb,'منصة موثوقة: مستخدمون صحيحو الأدوار، بيانات مكتملة، نسخ احتياطي منتظم.','دوري وعند تغيّر الفريق.','قائمة المنسوبين وأدوارهم، تقارير فاحص الجودة، سجل النسخ الاحتياطي.','حسابات معتمدة بأدوار صحيحة، مشاريع مرتبطة بمهندسيها، فحص جودة أسبوعي نظيف، نسخة احتياطية أسبوعية.','عدد ملاحظات فاحص الجودة المفتوحة؛ نجاح النسخ الاحتياطي الأسبوعي.','[{"unit": "PRJ", "role": "رئيس القسم", "action": "اعتماد الحسابات الجديدة وتعيين الدور الصحيح خلال يوم عمل، وتعطيل حسابات المغادرين فوراً", "sla": "يوم عمل", "where": "الإدارة ← المستخدمون", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "ربط كل مشروع بمهندسه المسؤول والتأكد أن لا مشروع بلا مهندس", "sla": "أسبوعي", "where": "الإدارة ← ربط المشاريع", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "تشغيل فاحص جودة البيانات ومعالجة ملاحظاته أو تكليف المهندسين بها", "sla": "أسبوعي", "where": "الإدارة ← جودة البيانات", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "مراجعة الإعدادات (مهلة الاعتماد، أيام الركود، تنبيهات الانتهاء والضمان) عند الحاجة", "sla": "ربع سنوي", "where": "الإدارة ← الإعدادات", "kind": "step"}, {"unit": "PRJ", "role": "المنصة (تلقائي)", "action": "نسخة احتياطية أسبوعية (Excel + قاعدة بيانات مشفرة) في مستودع خاص، وفحوص يومية للتنبيهات", "sla": "تلقائي", "where": "—", "kind": "step"}, {"unit": "PRJ", "role": "رئيس القسم", "action": "كل مستخدم يفعّل إشعارات جواله ويشترك في تقويمه من الإعدادات خلال أسبوع من إنشاء حسابه", "sla": "أسبوع", "where": "الإعدادات", "kind": "step"}]'::jsonb,'','1.0',115) on conflict (code) do nothing;
insert into public.gov_router(key,q,opts,sort) values ('start','ما نوع الاحتياج؟','[{"t": "عطل أو توقف في شيء قائم", "next": "fault"}, {"t": "احتياج جديد أو تحسين أو تغيير", "next": "new"}, {"t": "جهاز طبي جديد أو نقله", "out": {"unit": "MED", "proc": "G-07", "title": "التجهيزات الطبية", "text": "يُحدَّد الجهاز ومتطلبات موقعه، وتُجهَّز بالتنسيق مع المشاريع والصيانة قبل التوريد، وتستلمه الصيانة الطبية بعد التركيب."}}, {"t": "تقني: شبكة، حاسب، نظام، طابعة", "out": {"unit": "IT", "proc": "G-09", "title": "تقنية المعلومات", "text": "يُعالج عبر نظام الدعم التقني بحسب اتفاقية مستوى الخدمة."}}, {"t": "خدمة عامة: نظافة، أثاث غير طبي، نقل، أمن، نفايات", "out": {"unit": "GEN", "proc": "G-10", "title": "الخدمات العامة", "text": "طلب خدمة بمهلة 3 أيام عمل للطلبات العادية."}}]'::jsonb,0) on conflict (key) do nothing;
insert into public.gov_router(key,q,opts,sort) values ('fault','هل الحالة طارئة تهدد السلامة أو التشغيل الآن (تسرب، انقطاع في منطقة حرجة، حريق، مصعد)؟','[{"t": "نعم، طارئة", "out": {"unit": "MNT", "proc": "G-11", "title": "طوارئ الصيانة", "text": "اتصل مباشرة بغرفة الصيانة/الأمن؛ الاستجابة خلال ساعتين ويُسجَّل البلاغ لاحقاً."}}, {"t": "لا، يمكن انتظار المهلة العادية", "next": "fault2"}]'::jsonb,1) on conflict (key) do nothing;
insert into public.gov_router(key,q,opts,sort) values ('fault2','ما الذي تعطّل؟','[{"t": "جهاز طبي", "out": {"unit": "BME", "proc": "G-08", "title": "الصيانة الطبية", "text": "بلاغ بدرجة الخطورة: حرج فوراً، عالٍ 4 ساعات، عادي 24 ساعة."}}, {"t": "شبكة أو حاسب أو نظام", "out": {"unit": "IT", "proc": "G-09", "title": "تقنية المعلومات", "text": "بلاغ تقني عبر نظام الدعم."}}, {"t": "مبنى أو نظام (كهرباء، تكييف، سباكة، أبواب، إنارة…)", "out": {"unit": "MNT", "proc": "G-05", "title": "الصيانة", "text": "بلاغ صيانة تصحيحية: عاجل 24 ساعة، عادي 5 أيام عمل. إن تبيّن أن الإصلاح يحتاج تغيير تصميم أو يتجاوز حد المشروع يُحال إلى المشاريع."}}]'::jsonb,2) on conflict (key) do nothing;
insert into public.gov_router(key,q,opts,sort) values ('new','هل يتطلب تغييراً معمارياً أو إنشائياً أو تغييراً في استخدام المساحة، أو تصميماً ومخططات؟','[{"t": "نعم", "out": {"unit": "PRJ", "proc": "G-02", "title": "قسم المشاريع", "text": "يُحال طلب دراسة مشروع عبر المرافق؛ التسجيل خلال يوم عمل والدراسة خلال 10 أيام عمل."}}, {"t": "لا", "next": "new2"}]'::jsonb,3) on conflict (key) do nothing;
insert into public.gov_router(key,q,opts,sort) values ('new2','هل التكلفة التقديرية تتجاوز حد المشروع (100,000 ر.س مقترح) أو المدة تتجاوز 30 يوماً أو يشمل أكثر من تخصص؟','[{"t": "نعم", "out": {"unit": "PRJ", "proc": "G-02", "title": "قسم المشاريع", "text": "يستوفي معايير R-01 فيُدرس كمشروع."}}, {"t": "لا", "next": "new3"}]'::jsonb,4) on conflict (key) do nothing;
insert into public.gov_router(key,q,opts,sort) values ('new3','هل هو نقل قسم أو إعادة توزيع مساحة قائمة؟','[{"t": "نعم", "out": {"unit": "FAC", "proc": "G-12", "title": "المرافق — إدارة التغيير في المساحات", "text": "تقييم موحد ثم خطة انتقال بمشاركة الأقسام المعنية."}}, {"t": "لا، أعمال بسيطة (دهان، تثبيت، نقطة كهرباء، تعديل بسيط)", "out": {"unit": "MNT", "proc": "G-05", "title": "الصيانة — أعمال صغيرة", "text": "تُنفذ كأعمال صيانة دون الحد المالي للمشروع (R-02)."}}]'::jsonb,5) on conflict (key) do nothing;
insert into public.gov_faq(q,a,links,action,sort) select * from (values
('كيف نحدد أن الحالة صيانة أم مشروع؟','القاعدة R-01: يصبح الاحتياج مشروعاً إذا غيّر التصميم أو الإنشاء أو استخدام المساحة، أو تجاوز الحد المالي أو الزمني، أو احتاج تصميماً وطرحاً، أو تعدد تخصصاته. ما عدا ذلك يبقى صيانة أو خدمات (R-02). المرافق تصنّف خلال يوم عمل، وعند الشك تُدرس الحالة عند المشاريع خلال 10 أيام عمل وتُعاد إن لم تكن مشروعاً. جرّب «موجّه الطلبات» للإجابة في ثلاث خطوات.','["R-01", "R-02", "G-01", "G-02"]'::jsonb,'router',1),
('كيف تسلّم المشاريع مشروعاً منجزاً للمرافق والصيانة؟','عبر الإجراء G-04: لجنة استلام ابتدائي تضم المرافق والصيانة (وتقنية المعلومات والصيانة الطبية بحسب النطاق) والمنشأة، ثم محضر استلام بالملاحظات ومهلة إنهائها، ثم ملف تسليم خلال أسبوعين: مخططات كما نُفّذ، ضمانات، كتيبات، جداول صيانة وقائية، قائمة الأصول. بعدها تحدّث المرافق سجل الأصول وتدرج الصيانة الأنظمة في خطتها ويبدأ الضمان.','["G-04", "R-07", "P-13"]'::jsonb,'',2),
('كيف تستلم الصيانة مشروعاً أو نظاماً جديداً؟','تحضر الصيانة الاستلام الابتدائي وتفحص الأنظمة الميكانيكية والكهربائية وتسجل ملاحظاتها في المحضر، ثم تتسلم مع ملف التسليم جداول الصيانة الوقائية الموصى بها وقطع الغيار، وتدرج الأنظمة في خطة PPM وتسجل تاريخ بدء الضمان. أي عيب خلال الضمان تبلّغه للمشاريع خلال 3 أيام عمل لتطالب المقاول.','["G-04", "G-06", "P-14"]'::jsonb,'',3),
('كيف يبدأ أي احتياج من المنشأة؟','قناة واحدة: المنشأة ترفع الاحتياج أو البلاغ إلى المرافق (R-05)، فتسجله برقم وتصنّفه خلال يوم عمل وتوجهه للقسم المختص وتبلّغ المنشأة بالمهلة. الطوارئ فقط تُتصل مباشرة بالصيانة (G-11).','["R-05", "G-01", "G-11"]'::jsonb,'router',4),
('كيف تُعالج الأعطال في المباني والأنظمة؟','الإجراء G-05: أمر عمل بأولوية (طارئ ساعتان، عاجل 24 ساعة، عادي 5 أيام)، كشف وإصلاح وإغلاق بتوقيع المنشأة وتحديث سجل الأصل. إذا تبيّن أن الإصلاح يحتاج تغيير تصميم أو يتجاوز حد المشروع يُحال للمشاريع بتوصية.','["G-05", "R-02"]'::jsonb,'',5),
('كيف يُجهَّز موقع جهاز طبي جديد ومن يستلمه؟','الإجراء G-07: التجهيزات الطبية ترسل بطاقة متطلبات الموقع قبل التوريد بـ 60 يوماً، المشاريع تقيّمها (بسيطة → الصيانة، كبيرة → مشروع مصغّر)، تقنية المعلومات تجهز الربط، ثم محضر جاهزية الموقع قبل التوريد. بعد التركيب والتشغيل التجريبي والتدريب تستلم الصيانة الطبية الجهاز وتدرجه في سجل الأصول قبل دخوله الخدمة.','["G-07", "R-03"]'::jsonb,'',6),
('كيف تدخل تقنية المعلومات في المشاريع؟','القاعدة R-04 والإجراء G-09: كل نطاق يتضمن شبكات أو تيار خفيف تقني أو أنظمة يُراجَع من تقنية المعلومات قبل الطرح، وتُدرج مواصفاتها المعتمدة في الوثائق، وتحضر الاختبارات وتستلم الشهادات وتسجل الأصول التقنية عند الإنجاز.','["R-04", "G-09"]'::jsonb,'',7),
('كيف تُنفَّذ أعمال داخل منطقة مشغّلة دون التأثير على المرضى؟','القاعدة R-06 والإجراء G-10: خطة تنسيق قبل المباشرة بأسبوع تشمل موافقة مكافحة العدوى والحواجز ومسارات بديلة وأوقات العمل، الخدمات العامة تهيئ الموقع وتنظفه يومياً وتعيده للتشغيل في النهاية.','["R-06", "G-10"]'::jsonb,'',8),
('كيف يتحول نظام قديم متكرر الأعطال إلى مشروع تطوير؟','الصيانة توصي بالاستبدال عندما يتكرر العطل أو تتجاوز كلفة الإصلاح 40٪ من قيمة الاستبدال أو ينتهي العمر الافتراضي، مع تقرير حالة، فتُدرس التوصية عند المشاريع (G-02) وتُدرج في الخطة السنوية بحسب الأولوية.','["G-02", "G-06"]'::jsonb,'',9),
('كيف نتصرف في الطوارئ؟','الإجراء G-11: اتصال مباشر بغرفة الصيانة أو الأمن، استجابة واحتواء خلال ساعتين، إبلاغ المرافق ومدير الإدارة خلال ساعة، الخدمات العامة تؤمّن الموقع، ثم تسجيل البلاغ وتقرير الواقعة خلال 48 ساعة وتوجيه الإجراءات التصحيحية.','["G-11", "R-09"]'::jsonb,'',10),
('كيف نغيّر استخدام مساحة أو ننقل قسماً؟','الإجراء G-12: المرافق تقيّم الطلب مع المخططات والاشتراطات خلال 5 أيام عمل، وتوزع الأعمال: إنشائية → المشاريع، فنية بسيطة → الصيانة، تقنية → تقنية المعلومات، أجهزة → التجهيزات والصيانة الطبية، أثاث ونقل → الخدمات العامة، ثم تحدّث المخططات المعتمدة.','["G-12"]'::jsonb,'',11),
('من يعتمد ماذا؟ وما حدود الصلاحية؟','مصفوفة الصلاحيات تبيّن لكل نشاط من يعتمد (A) ومن ينفّذ (R) ومن يراجع (V) ومن يُستشار (C) ومن يُبلَّغ (I). الحدود المالية والزمنية في R-08: ضمن الحدود الداخلية مدير الإدارة، وفوقها الإدارة التنفيذية. القيم المقترحة تحتاج اعتماداً.','["R-08"]'::jsonb,'matrix',12),
('ماذا لو اختلف قسمان على من يختص؟','القاعدة R-10: المرافق ترفع الخلاف لمدير الإدارة فيفصل خلال يومي عمل، ويُسجَّل القرار كسابقة تُضاف إلى القواعد حتى لا يتكرر الخلاف. المبدأ: التعاون أولاً، ومن يستطيع الحل يبدأ ثم يُسوّى الاختصاص.','["R-10"]'::jsonb,'',13)
