-- ===== الحوكمة: الهيكل والعلاقات، نقاط التسليم، القواعد الحاكمة، مصفوفة الصلاحيات، الإجراءات، موجّه الطلبات (بذور قابلة للتعديل من الموقع) =====
create table if not exists public.gov_units (code text primary key, name text not null, short text not null, kind text not null default 'unit' check (kind in ('unit','mgmt','ext')), color text default '6B7A88', mission text default '', duties jsonb default '[]', head text default '', sort int default 0, active boolean default true);
create table if not exists public.gov_handoffs (id bigserial primary key, from_unit text references public.gov_units(code), to_unit text references public.gov_units(code), trigger text not null, deliverable text default '', sla text default '', process_code text default '', note text default '', sort int default 0);
create table if not exists public.gov_rules (code text primary key, title text not null, theme text default '', statement text not null, criteria jsonb default '[]', owner text references public.gov_units(code), process_code text default '', note text default '', sort int default 0, active boolean default true);
create table if not exists public.gov_activities (id bigserial primary key, scope text not null default 'units', grp text default '', title text not null, raci jsonb not null default '{}', note text default '', sort int default 0);
create table if not exists public.gov_processes (code text primary key, title text not null, owner text references public.gov_units(code), units jsonb default '[]', goal text default '', trigger text default '', inputs text default '', outputs text default '', kpi text default '', steps jsonb default '[]', notes text default '', version text default '1.0', status text default 'draft' check (status in ('draft','approved')), approved_by text default '', approved_at date, sort int default 0, active boolean default true, updated_at timestamptz default now());
create table if not exists public.gov_router (key text primary key, q text not null, opts jsonb not null default '[]', sort int default 0);
create table if not exists public.gov_faq (id bigserial primary key, q text not null, a text not null, links jsonb default '[]', action text default '', sort int default 0);
do $$ declare t text; begin
  foreach t in array array['gov_units','gov_handoffs','gov_rules','gov_activities','gov_processes','gov_router','gov_faq'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('drop policy if exists p_read on public.%I', t); execute format('create policy p_read on public.%I for select using (public.can_read())', t);
    execute format('drop policy if exists p_admin on public.%I', t); execute format('create policy p_admin on public.%I for all using (public.is_admin()) with check (public.is_admin())', t);
  end loop; end $$;
grant usage, select on sequence public.gov_handoffs_id_seq to authenticated; grant usage, select on sequence public.gov_activities_id_seq to authenticated; grant usage, select on sequence public.gov_faq_id_seq to authenticated;
) as v(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) where not exists (select 1 from public.gov_handoffs);
) as v(scope,grp,title,raci,sort) where not exists (select 1 from public.gov_activities);
) as v(q,a,links,action,sort) where not exists (select 1 from public.gov_faq);
